      && verifier.VerifyField(tablePos, 36 /*CLOCK_RATE_BASE*/, 8 /*double*/, 8, false)
      && verifier.VerifyVectorOfStrings(tablePos, 38 /*COMMENT*/, false)
      && verifier.VerifyTableEnd(tablePos);
  }
}
